files.content:
:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --accent: #e94560;
  --accent-hover: #ff6b81;
  --text: #eaeaea;
  --muted: #8a8a9a;
  --pixel-on: #e94560;
  --pixel-off: #2a2a4a;
  --font: 'Courier New', Courier, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 32px 24px;
  width: 100%;
  max-width: 480px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

.title {
  font-size: 1.5rem;
  letter-spacing: 4px;
  text-transform: uppercase;
  color: var(--accent);
  text-align: center;
}

.clock-section {
  width: 100%;
  display: flex;
  justify-content: center;
}

.pixel-clock {
  font-size: clamp(2rem, 10vw, 3.5rem);
  font-weight: bold;
  letter-spacing: 6px;
  color: var(--pixel-on);
  text-shadow: 0 0 10px rgba(233, 69, 96, 0.6), 0 0 20px rgba(233, 69, 96, 0.3);
  background: var(--pixel-off);
  padding: 16px 20px;
  border-radius: 8px;
  border: 2px solid var(--accent);
  text-align: center;
  min-width: 0;
  word-break: break-all;
  font-variant-numeric: tabular-nums;
}

.controls {
  display: flex;
  justify-content: center;
  width: 100%;
}

.toggle-btn {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--pixel-off);
  color: var(--text);
  border: 2px solid var(--accent);
  border-radius: 8px;
  padding: 12px 20px;
  font-family: var(--font);
  font-size: 1rem;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, transform 0.05s;
}

.toggle-btn:hover {
  background: var(--accent);
  border-color: var(--accent-hover);
}

.toggle-btn:focus-visible {
  outline: 3px solid var(--accent-hover);
  outline-offset: 3px;
}

.toggle-btn:active {
  transform: scale(0.97);
  background: var(--accent-hover);
}

.toggle-switch {
  width: 40px;
  height: 22px;
  background: var(--muted);
  border-radius: 11px;
  position: relative;
  transition: background 0.2s;
}

.toggle-switch::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 16px;
  height: 16px;
  background: var(--text);
  border-radius: 50%;
  transition: transform 0.2s;
}

.toggle-btn[aria-pressed="true"] .toggle-switch {
  background: var(--accent);
}

.toggle-btn[aria-pressed="true"] .toggle-switch::after {
  transform: translateX(18px);
}

.stopwatch-section {
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  border-top: 2px solid var(--pixel-off);
  padding-top: 20px;
}

.stopwatch-title {
  font-size: 1rem;
  color: var(--muted);
  letter-spacing: 2px;
  text-transform: uppercase;
  font-weight: normal;
}

.stopwatch {
  font-size: clamp(1.25rem, 6vw, 1.75rem);
  font-weight: bold;
  letter-spacing: 4px;
  color: var(--text);
  font-variant-numeric: tabular-nums;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .pixel-clock {
    letter-spacing: 3px;
    padding: 12px 14px;
  }
}

(function () {
  'use strict';

  var clockEl = document.getElementById('clock');
  var stopwatchEl = document.getElementById('stopwatch');
  var toggleBtn = document.getElementById('format-toggle');
  var toggleLabel = toggleBtn.querySelector('.toggle-label');

  var use12Hour = false;
  var startTime = Date.now();

  function pad(n) {
    return n < 10 ? '0' + n : String(n);
  }

  function formatClock(date) {
    var h = date.getHours();
    var m = date.getMinutes();
    var s = date.getSeconds();
    var suffix = '';

    if (use12Hour) {
      suffix = h >= 12 ? ' PM' : ' AM';
      h = h % 12;
      if (h === 0) h = 12;
    }

    return pad(h) + ':' + pad(m) + ':' + pad(s) + suffix;
  }

  function formatElapsed(ms) {
    var totalSeconds = Math.floor(ms / 1000);
    var hours = Math.floor(totalSeconds / 3600);
    var minutes = Math.floor((totalSeconds % 3600) / 60);
    var seconds = totalSeconds % 60;
    return pad(hours) + ':' + pad(minutes) + ':' + pad(seconds);
  }

  function update() {
    var now = new Date();
    clockEl.textContent = formatClock(now);
    stopwatchEl.textContent = formatElapsed(Date.now() - startTime);
  }

  function toggleFormat() {
    use12Hour = !use12Hour;
    toggleBtn.setAttribute('aria-pressed', String(use12Hour));
    toggleLabel.textContent = use12Hour ? '12-hour' : '24-hour';
    toggleBtn.setAttribute('aria-label', use12Hour ? 'Switch to 24-hour format' : 'Switch to 12-hour format');
    update();
  }

  toggleBtn.addEventListener('click', toggleFormat);

  update();
  setInterval(update, 1000);
})();
